export class HttpError extends Error {
  constructor(status, message, details) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

export function notFound(req, res) {
  res.status(404).json({ error: `Rute ${req.method} ${req.path} tidak ada` });
}

// Express mengenali middleware error dari jumlah parameternya (4),
// jadi `next` harus tetap ditulis walau tidak dipakai.
export function errorHandler(err, req, res, next) {
  if (err instanceof HttpError) {
    return res.status(err.status).json({ error: err.message, details: err.details });
  }
  if (err.type === "entity.parse.failed") {
    return res.status(400).json({ error: "Body bukan JSON yang valid" });
  }
  if (err.expose && err.status) {
    return res.status(err.status).json({ error: err.message });
  }
  console.error(err);
  res.status(500).json({ error: "Terjadi kesalahan di server" });
}

import { HttpError } from "./errors.js";

const MAX_INT = 2147483647;

export function parseId(raw) {
  const id = Number(raw);
  if (!Number.isInteger(id) || id < 1 || id > MAX_INT) {
    throw new HttpError(400, "id harus bilangan bulat positif");
  }
  return id;
}

// partial = true dipakai PATCH: field boleh tidak dikirim, tapi minimal satu.
export function parseNote(body, { partial = false } = {}) {
  if (body === null || typeof body !== "object" || Array.isArray(body)) {
    throw new HttpError(400, "Body harus berupa objek JSON");
  }

  const errors = {};
  const note = {};

  if (body.title !== undefined) {
    const title = typeof body.title === "string" ? body.title.trim() : "";
    if (title.length === 0) errors.title = "wajib berupa teks dan tidak boleh kosong";
    else if (title.length > 120) errors.title = "maksimal 120 karakter";
    else note.title = title;
  } else if (!partial) {
    errors.title = "wajib diisi";
  }

  if (body.content !== undefined) {
    if (typeof body.content !== "string") errors.content = "harus berupa teks";
    else if (body.content.length > 10000) errors.content = "maksimal 10000 karakter";
    else note.content = body.content;
  }

  if (body.pinned !== undefined) {
    if (typeof body.pinned !== "boolean") errors.pinned = "harus true atau false";
    else note.pinned = body.pinned;
  }

  if (Object.keys(errors).length > 0) {
    throw new HttpError(422, "Data catatan tidak valid", errors);
  }
  if (partial && Object.keys(note).length === 0) {
    throw new HttpError(400, "Kirim minimal satu field: title, content, atau pinned");
  }
  return note;
}

