import { Router } from "express";
import { pool } from "../db.js";
import { HttpError } from "../errors.js";
import { parseId } from "../validate.js";

export const notes = Router();

notes.get("/", async (req, res) => {
  const q = typeof req.query.q === "string" ? req.query.q.trim() : "";
  const limit = Math.min(Math.max(Number.parseInt(req.query.limit, 10) || 20, 1), 100);

  // Nilai dari pengguna selalu lewat $1, $2, ... dan tidak pernah
  // ditempel ke string SQL. Itulah yang mencegah SQL injection.
  const { rows } = await pool.query(
    `SELECT * FROM notes
     WHERE $1 = '' OR title ILIKE '%' || $1 || '%' OR content ILIKE '%' || $1 || '%'
     ORDER BY pinned DESC, updated_at DESC
     LIMIT $2`,
    [q, limit]
  );
  res.json(rows);
});

notes.get("/:id", async (req, res) => {
  const id = parseId(req.params.id);
  const { rows } = await pool.query("SELECT * FROM notes WHERE id = $1", [id]);
  if (rows.length === 0) throw new HttpError(404, "Catatan tidak ditemukan");
  res.json(rows[0]);
});

import express from "express";
import { pool } from "./db.js";
import { errorHandler, notFound } from "./errors.js";
import { notes } from "./routes/notes.js";

export const app = express();

app.use(express.json({ limit: "100kb" }));

app.get("/health", async (req, res) => {
  await pool.query("SELECT 1");
  res.json({ status: "ok" });
});

app.use("/api/notes", notes);

// Dua baris ini harus selalu paling bawah.
app.use(notFound);
app.use(errorHandler);

// Tambahkan di bawah rute GET pada src/routes/notes.js,
// dan ubah import validasi menjadi:
// import { parseId, parseNote } from "../validate.js";

notes.post("/", async (req, res) => {
  const note = parseNote(req.body);
  const { rows } = await pool.query(
    `INSERT INTO notes (title, content, pinned)
     VALUES ($1, $2, $3)
     RETURNING *`,
    [note.title, note.content ?? "", note.pinned ?? false]
  );
  res.status(201).location(`/api/notes/${rows[0].id}`).json(rows[0]);
});

notes.patch("/:id", async (req, res) => {
  const id = parseId(req.params.id);
  const note = parseNote(req.body, { partial: true });

  // COALESCE: kalau field tidak dikirim (null), nilai lama dipertahankan.
  const { rows } = await pool.query(
    `UPDATE notes SET
       title = COALESCE($2, title),
       content = COALESCE($3, content),
       pinned = COALESCE($4, pinned),
       updated_at = now()
     WHERE id = $1
     RETURNING *`,
    [id, note.title ?? null, note.content ?? null, note.pinned ?? null]
  );
  if (rows.length === 0) throw new HttpError(404, "Catatan tidak ditemukan");
  res.json(rows[0]);
});

notes.delete("/:id", async (req, res) => {
  const id = parseId(req.params.id);
  const { rowCount } = await pool.query("DELETE FROM notes WHERE id = $1", [id]);
  if (rowCount === 0) throw new HttpError(404, "Catatan tidak ditemukan");
  res.status(204).end();
});

import { test, after } from "node:test";
import assert from "node:assert/strict";
import request from "supertest";
import { app } from "../src/app.js";
import { pool } from "../src/db.js";

// Tutup koneksi database supaya proses tes bisa selesai.
after(() => pool.end());

test("GET /health mengembalikan ok", async () => {
  const res = await request(app).get("/health");
  assert.equal(res.status, 200);
  assert.deepEqual(res.body, { status: "ok" });
});

test("alur lengkap: buat, baca, ubah, hapus", async () => {
  const created = await request(app)
    .post("/api/notes")
    .send({ title: "Belanja", content: "Beras, telur" });
  assert.equal(created.status, 201);
  const id = created.body.id;
  assert.equal(created.headers.location, `/api/notes/${id}`);

  const read = await request(app).get(`/api/notes/${id}`);
  assert.equal(read.status, 200);
  assert.equal(read.body.title, "Belanja");

  const updated = await request(app).patch(`/api/notes/${id}`).send({ pinned: true });
  assert.equal(updated.status, 200);
  assert.equal(updated.body.pinned, true);
  assert.equal(updated.body.title, "Belanja");

  const deleted = await request(app).delete(`/api/notes/${id}`);
  assert.equal(deleted.status, 204);

  const gone = await request(app).get(`/api/notes/${id}`);
  assert.equal(gone.status, 404);
});

test("POST tanpa title ditolak dengan 422", async () => {
  const res = await request(app).post("/api/notes").send({ content: "tanpa judul" });
  assert.equal(res.status, 422);
  assert.ok(res.body.details.title);
});

test("id yang bukan angka ditolak dengan 400", async () => {
  const res = await request(app).get("/api/notes/abc");
  assert.equal(res.status, 400);
});

test("JSON rusak ditolak dengan 400", async () => {
  const res = await request(app)
    .post("/api/notes")
    .set("Content-Type", "application/json")
    .send('{"title": ');
  assert.equal(res.status, 400);
});
